WITH prev_events AS (SELECT *, LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) AS prev_txn_time FROM transactions), gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '60' DAY THEN 1 ELSE 0 END AS session_start_flag FROM prev_events), sessions_transactions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT s.id, s.account_id, s.txn_type, s.amount, s.txn_time, s.merchant, s.is_flagged, s.prev_txn_time, s.session_no, CASE WHEN txn_type RLIKE '^(FEE|DEBIT)$' THEN 'GROUP_B' WHEN txn_type RLIKE '^(CREDIT|REFUND)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS txn_type_zone, (SELECT MIN(x.amount) FROM transactions x WHERE x.account_id = s.account_id) AS min_transaction_amount FROM sessions_transactions s ORDER BY amount NULLS FIRST;
